CREATE OR REPLACE FUNCTION public.compat_conversations_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  other uuid;
  cid uuid;
begin
  if me is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if new.participant_1_id = me then other := new.participant_2_id;
  elsif new.participant_2_id = me then other := new.participant_1_id;
  else raise exception 'not a participant' using errcode = '42501';
  end if;
  cid := public.chat_conversation_for(other);
  select c.id, c.user_a, c.user_b, c.created_at
    into new.id, new.participant_1_id, new.participant_2_id, new.created_at
  from public.chat_conversations c where c.id = cid;
  return new;
end $function$;
revoke all on function public.compat_conversations_insert() from public, anon, authenticated, service_role;
grant execute on function public.compat_conversations_insert() to public, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.compat_messages_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  c public.chat_conversations;
  other uuid;
  m public.chat_messages;
begin
  if me is null then raise exception 'not signed in' using errcode = '28000'; end if;
  select * into c from public.chat_conversations where id = new.conversation_id;
  if not found or me not in (c.user_a, c.user_b) then
    raise exception 'not a participant' using errcode = '42501';
  end if;
  other := case when c.user_a = me then c.user_b else c.user_a end;
  if not public.friends_are(me, other) then
    raise exception 'you can only message friends' using errcode = '42501';
  end if;
  if public.friends_blocked(me, other) then
    raise exception 'you cannot message this person' using errcode = '42501';
  end if;
  if new.text is null and new.post_id is null then
    raise exception 'empty message' using errcode = '22023';
  end if;
  insert into public.chat_messages (conversation_id, sender_id, body, post_id, was_post)
  values (new.conversation_id, me, new.text, new.post_id, new.post_id is not null)
  returning * into m;
  update public.chat_conversations set last_message_at = m.created_at where id = c.id;
  new.id := m.id;
  new.sender_id := me;
  new.created_at := m.created_at;
  return new;
end $function$;
revoke all on function public.compat_messages_insert() from public, anon, authenticated, service_role;
grant execute on function public.compat_messages_insert() to public, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.chat_can_send_post(p_post_id uuid, p_sender uuid, p_to uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  p record;
begin
  select * into p from public.posts where id = p_post_id;
  if not found or p.parent_post_id is not null or p.moderation_status <> 'active' then return false; end if;
  if p.is_mature and public.friends_is_minor(p_to) then return false; end if;
  if p.status = 'survived' or (p.status = 'expired' and p.survived_at is not null) then
    -- a survived post stays posted: any friend, if the video still exists
    if p.media_deleted_at is not null then return false; end if;
    if public.friends_blocked(p.user_id, p_to) then return false; end if;
    return true;
  elsif p.status = 'trial' then
    if p.user_id = p_sender then return true; end if;           -- the creator, to their own friends
    if p.user_id = p_to then return false; end if;
    if not public.trial_exposed(p.id, p_sender) then return false; end if;                 -- no guessing of ids
    if public.friends_blocked(p.user_id, p_to) then return false; end if;
    -- the creator's known people (contacts either direction, hide list, friends) never get it before it survives
    return not exists (select 1 from public.known_connections k where k.user_id = p.user_id and k.other_id = p_to);
  end if;
  return false;
end;
$function$;
revoke all on function public.chat_can_send_post(p_post_id uuid, p_sender uuid, p_to uuid) from public, anon, authenticated, service_role;
grant execute on function public.chat_can_send_post(p_post_id uuid, p_sender uuid, p_to uuid) to service_role;

CREATE OR REPLACE FUNCTION public.chat_post_available(p_post_id uuid, p_recipient uuid, p_sender uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return exists (
    select 1 from public.posts p
    where p.id = p_post_id
      and p.parent_post_id is null
      and p.moderation_status = 'active'
      and not (p.is_mature and public.friends_is_minor(p_recipient))
      and (
        -- survived (stays posted): any friend, if the video still exists and the creator has not blocked them
        ((p.status = 'survived' or (p.status = 'expired' and p.survived_at is not null))
          and p.media_deleted_at is null
          and not public.friends_blocked(p.user_id, p_recipient))
        or
        -- still testing: only to people the creator does not know; the creator may send it to their own friends
        (p.status = 'trial' and (
           p.user_id = p_sender
           or p.user_id = p_recipient
           or not exists (select 1 from public.known_connections k where k.user_id = p.user_id and k.other_id = p_recipient)
        ))
      )
  );
end;
$function$;
revoke all on function public.chat_post_available(p_post_id uuid, p_recipient uuid, p_sender uuid) from public, anon, authenticated, service_role;
grant execute on function public.chat_post_available(p_post_id uuid, p_recipient uuid, p_sender uuid) to service_role;

CREATE OR REPLACE FUNCTION public.expire_posts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  total integer := 0;
  n integer;
  guard integer := 0;
begin
  update public.posts p
  set distribution_expires_at = null
  where p.status = 'survived'
    and p.distribution_expires_at is not null
    and p.distribution_expires_at <= now();
  get diagnostics n = row_count;
  total := total + n;

  loop
    update public.posts c
    set status = 'expired',
        expired_at = now()
    from public.posts p
    where c.parent_post_id = p.id
      and c.status not in ('expired', 'archived')
      and (p.status = 'archived' or (p.status = 'expired' and p.survived_at is null));
    get diagnostics n = row_count;
    total := total + n;

    guard := guard + 1;
    exit when n = 0 or guard >= 5;
  end loop;

  return total;
end;
$function$;
revoke all on function public.expire_posts() from public, anon, authenticated, service_role;
grant execute on function public.expire_posts() to public, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.get_feed_engine(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_seen uuid[] DEFAULT '{}'::uuid[])
 RETURNS TABLE(post_id uuid, "position" integer, page_rows integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  cfg public.trial_engine_config := public.trial_cfg();
  hide_mature boolean := false;
  seen uuid[] := coalesce(p_seen, '{}');
  use_seen boolean := coalesce(cardinality(p_seen), 0) > 0;
  assigned uuid[] := '{}';
  boosted uuid[] := '{}';
  front uuid[];
  a_count integer;
  take_front uuid[];
  rest_limit integer;
  rest_offset integer;
  rest_ids uuid[] := '{}';
  src_rows integer := 0;
  feed_ok boolean := to_regprocedure('public.get_feed(integer,integer)') is not null;
  out_ids uuid[];
  avail integer;
begin
  if cfg.engine_mode = 'legacy' or me is null then
    if feed_ok then
      return query execute 'select f.post_id, f.position::integer, (select count(*)::integer from public.get_feed($1, $2)) from public.get_feed($1, $2) f' using p_limit, p_offset;
    end if;
    return;
  end if;

  select coalesce(public.age_tier(pr.birthdate) in ('under_13', 'teen'), false) into hide_mature
  from public.profiles pr where pr.id = me;
  hide_mature := coalesce(hide_mature, false);

  if p_offset = 0 and not use_seen then
    begin
      perform public.trial_assign_on_demand(me);
    exception when others then
      null;
    end;
  end if;

  select coalesce(array_agg(x.post_id order by x.rr, x.created_at, x.post_id), '{}') into assigned
  from (
    select t.post_id, p.created_at,
           row_number() over (partition by p.user_id order by p.created_at, p.id) as rr
    from public.trial_assignments t
    join public.posts p on p.id = t.post_id
    where t.viewer_id = me and t.released_at is null and p.status = 'trial' and p.parent_post_id is null and p.moderation_status = 'active'
      and p.user_id <> me and p.media_deleted_at is null
      and (not hide_mature or not p.is_mature)
      and not public.trial_is_silenced(p.user_id, me)
      and not exists (select 1 from public.feed_blocked_ids() b(id) where b.id = p.user_id)
      and not exists (select 1 from public.reports r where r.reporter_id = me and r.target_type = 'post' and r.target_id = p.id)
      and not public.trial_exposed(t.post_id, me)
      and not (t.post_id = any (seen))
  ) x;

  select coalesce(array_agg(x.id), '{}') into boosted
  from (
    select p.id from public.posts p
    join public.viewer_creator_affinity a on a.creator_id = p.user_id and a.viewer_id = me and a.score >= cfg.affinity_threshold
    where p.status = 'survived' and p.parent_post_id is null and p.moderation_status = 'active'
      and (p.distribution_expires_at is null or p.distribution_expires_at > now())
      and p.user_id <> me and p.media_deleted_at is null
      and (not hide_mature or not p.is_mature)
      and not exists (select 1 from public.feed_blocked_ids() b(id) where b.id = p.user_id)
      and not exists (select 1 from public.reports r where r.reporter_id = me and r.target_type = 'post' and r.target_id = p.id)
      and not public.trial_exposed(p.id, me)
      and not (p.id = any (seen))
      and not public.trial_feed_hidden(p.user_id, me)
    order by a.score desc, p.survived_at desc nulls last
    limit cfg.affinity_feed_boost
  ) x;

  front := assigned || array(select b from unnest(boosted) b where not (b = any (assigned)));
  a_count := coalesce(cardinality(front), 0);

  if use_seen then
    take_front := front[1 : least(a_count, p_limit)];
    rest_limit := p_limit - coalesce(cardinality(take_front), 0);
    rest_offset := 0;
  elsif p_offset < a_count then
    take_front := front[p_offset + 1 : least(a_count, p_offset + p_limit)];
    rest_limit := p_limit - coalesce(cardinality(take_front), 0);
    rest_offset := 0;
  else
    take_front := '{}';
    rest_limit := p_limit;
    rest_offset := p_offset - a_count;
  end if;

  -- SURVIVED POSTS after every testing post. In-window survived posts first; then, as a last resort when the feed
  -- would otherwise run dry, posts that survived and whose 24 h window has ended (status 'expired' with survived_at).
  -- Each tier: unseen before seen, every creator's best before anyone's second, most liked first.
  select coalesce(array_agg(x.id order by x.expired, x.was_seen, x.creator_rank, x.score desc, x.survived_at desc nulls last, x.id), '{}')
    into rest_ids
  from (
    select p.id, p.survived_at, e.score, f.expired,
           exists (select 1 from public.post_raw_views v where v.post_id = p.id and v.viewer_id = me) as was_seen,
           row_number() over (
             partition by p.user_id, f.expired
             order by e.score desc, p.survived_at desc nulls last, p.id) as creator_rank
    from public.posts p
    cross join lateral (
      select (p.status = 'expired'
              or (p.distribution_expires_at is not null and p.distribution_expires_at <= now())) as expired
    ) f
    cross join lateral (
      select (select count(*) from public.likes l where l.post_id = p.id and l.user_id <> p.user_id)
             + cfg.survived_reaction_weight
               * (select count(distinct r.user_id) from public.posts r where r.parent_post_id = p.id and r.user_id <> p.user_id)
             as score
    ) e
    where (p.status = 'survived' or (p.status = 'expired' and p.survived_at is not null))
      and p.parent_post_id is null and p.moderation_status = 'active' and p.media_deleted_at is null
      and (not hide_mature or not p.is_mature)
      and not exists (select 1 from public.feed_blocked_ids() b(id) where b.id = p.user_id)
      and not exists (select 1 from public.reports r where r.reporter_id = me and r.target_type = 'post' and r.target_id = p.id)
      and (p.user_id = me or not public.trial_feed_hidden(p.user_id, me))
      and not (p.id = any (front)) and not (p.id = any (seen))
  ) x;
  src_rows := coalesce(cardinality(rest_ids), 0);

  if use_seen then
    avail := a_count + src_rows;
    rest_ids := rest_ids[1 : greatest(rest_limit, 0)];
  else
    rest_ids := rest_ids[rest_offset + 1 : rest_offset + greatest(rest_limit, 0)];
    avail := coalesce(cardinality(take_front), 0) + coalesce(cardinality(rest_ids), 0);
  end if;

  out_ids := coalesce(take_front, '{}') || coalesce(rest_ids, '{}');
  if coalesce(cardinality(out_ids), 0) = 0 then
    return query select null::uuid, -1, avail;
    return;
  end if;
  return query
    select o.id, (p_offset + o.ord)::integer, avail
    from unnest(out_ids) with ordinality as o(id, ord);
end;
$function$;
revoke all on function public.get_feed_engine(p_limit integer, p_offset integer, p_seen uuid[]) from public, anon, authenticated, service_role;
grant execute on function public.get_feed_engine(p_limit integer, p_offset integer, p_seen uuid[]) to public, anon, authenticated, service_role;

